from bisect import bisect_right


def two_sum(xs, target):
    """
    Return the pair of indices (i, j) with i < j such that
    xs[i] + xs[j] == target, or None if no such pair exists.

    If several pairs exist, the one with the smallest i is returned,
    and among those, the one with the smallest j.
    """
    positions = {}
    for idx, value in enumerate(xs):
        positions.setdefault(value, []).append(idx)

    for i, value in enumerate(xs):
        complement = target - value
        if complement in positions:
            candidates = positions[complement]
            pos = bisect_right(candidates, i)
            if pos < len(candidates):
                return (i, candidates[pos])

    return None
